def transform(grid):
    h, w = len(grid), len(grid[0])

    # Full-width and full-height separator lines.
    sep_rows = [r for r in range(h) if all(v == grid[r][0] for v in grid[r])]
    sep_cols = [c for c in range(w) if all(grid[0][c] == grid[r][c] for r in range(h))]

    # The separator color appears at every crossing; select the most common
    # color among the full separator rows.
    sep_color = max(set(grid[sep_rows[0]]), key=grid[sep_rows[0]].count)

    row_bounds = [-1] + sep_rows + [h]
    col_bounds = [-1] + sep_cols + [w]
    row_panels = [(row_bounds[i] + 1, row_bounds[i + 1]) for i in range(len(row_bounds) - 1)]
    col_panels = [(col_bounds[i] + 1, col_bounds[i + 1]) for i in range(len(col_bounds) - 1)]

    # Find the non-first-column panel containing the template shape.
    shape = None
    for pr, (r0, r1) in enumerate(row_panels):
        for pc, (c0, c1) in enumerate(col_panels):
            if pc == 0:
                continue
            cells = [(r - r0, c - c0, grid[r][c])
                     for r in range(r0, r1) for c in range(c0, c1)
                     if grid[r][c] != 0 and grid[r][c] != sep_color]
            if cells:
                template_color = cells[0][2]
                shape = [(dr, dc) for dr, dc, color in cells if color == template_color]
                break
        if shape is not None:
            break

    out = [[sep_color if r in sep_rows or c in sep_cols else 0
            for c in range(w)] for r in range(h)]

    for r0, r1 in row_panels:
        # The first panel in each panel-row supplies the color to use.
        seed_colors = [grid[r][c]
                       for r in range(r0, r1)
                       for c in range(col_panels[0][0], col_panels[0][1])
                       if grid[r][c] not in (0, sep_color)]
        if not seed_colors:
            continue
        color = max(set(seed_colors), key=seed_colors.count)
        for c0, c1 in col_panels:
            for dr, dc in shape or []:
                if r0 + dr < r1 and c0 + dc < c1:
                    out[r0 + dr][c0 + dc] = color

    return out
